from unittest.mock import patch
def forward(options):
    with patch.object(**options):
        pass
opts = {'target': mod, 'attribute': 'public'}
args = (opts,)
opts = {'target': mod, 'attribute': '_data'}
forward(*args)

def lookup(name):
    return getattr(mod, name, int)
def annotated(value: lookup('public')):
    pass

def test_it():
    name = 'public'
    def annotation(value):
        nonlocal name
        name = value
        return int
    def annotated(value: annotation('_data')):
        pass
    getattr(mod, name)

def test_it():
    name = 'public'
    def lookup():
        return getattr(mod, name, int)
    def annotated(value: lookup()):
        pass
    name = 'public'

def gen():
    return (yield None)
pending = gen()
next(pending)
getattr(mod, 'public')

items=(getattr(mod,name) for name in ('public','_helper'))
for _ in items:
    break

